\set ON_ERROR_STOP on
begin;
create or replace function finance_api.authorize_scope(p_legal_entity_id uuid,p_dealer_account_id uuid,p_branch_id uuid,p_operation_id text) returns boolean language sql stable security definer set search_path='' as $$select p_operation_id in('getCurrentFranchiseContract','listContractVersions','getContractVersionEvidence')$$;
do $test$
declare maker constant uuid:='10000000-0000-4000-8000-000000000001';checker constant uuid:='10000000-0000-4000-8000-000000000002';hq constant uuid:='11000000-0000-4000-8000-000000000001';dealer constant uuid:='12000000-0000-4000-8000-000000000001';branch constant uuid:='13000000-0000-4000-8000-000000000001';account constant uuid:='14000000-0000-4000-8000-000000000001';contract_id constant uuid:='15000000-0000-4000-8000-000000000001';active_version constant uuid:='16000000-0000-4000-8000-000000000001';candidate_version constant uuid:='16000000-0000-4000-8000-000000000002';fee_royalty constant uuid:='17000000-0000-4000-8000-000000000001';fee_entry constant uuid:='17000000-0000-4000-8000-000000000002';fee_unsupported constant uuid:='17000000-0000-4000-8000-000000000003';tax_code constant uuid:='18000000-0000-4000-8000-000000000001';tax_version constant uuid:='18000000-0000-4000-8000-000000000002';corr constant uuid:='19000000-0000-4000-8000-000000000001';doc_ref constant uuid:='1a000000-0000-4000-8000-000000000001';doc_external constant uuid:='1b000000-0000-4000-8000-000000000001';scenario jsonb;result jsonb;timeline jsonb;locator jsonb;before_count integer;after_count integer;
begin
 insert into finance.legal_entities(id,entity_code,legal_name,status,created_by,correlation_id) values(hq,'IMPACT-HQ','Sentetik Etki Merkezi','ACTIVE',maker,corr);
 insert into finance.dealer_legal_entities(id,legal_entity_id,dealer_code,legal_name,status,created_by,correlation_id) values(dealer,hq,'IMPACT-DEALER','Sentetik Etki Bayisi','ACTIVE',maker,corr);
 insert into finance.branches(id,legal_entity_id,dealer_legal_entity_id,branch_code,status,created_by,correlation_id) values(branch,hq,dealer,'IMPACT-BRANCH','ACTIVE',maker,corr);
 insert into finance.dealer_accounts(id,legal_entity_id,dealer_legal_entity_id,account_code,currency_code,status,created_by,correlation_id) values(account,hq,dealer,'IMPACT-ACCOUNT','TRY','ACTIVE',maker,corr);
 insert into finance.fee_definitions(id,legal_entity_id,code,version_no,fee_family,name,status,created_by,correlation_id) values
 (fee_royalty,hq,'ROYALTY',1,'ROYALTY','Royalty', 'PUBLISHED',maker,corr),(fee_entry,hq,'ENTRY',1,'ENTRY_FRANCHISE','Giriş Bedeli','PUBLISHED',maker,corr),(fee_unsupported,hq,'TIERED',1,'OPTIONAL_PRODUCT_SERVICE','Kademeli Bedel','PUBLISHED',maker,corr);
 insert into finance.tax_codes(id,legal_entity_id,country_code,code,description,status,created_by,correlation_id) values(tax_code,hq,'TR','KDV20','Sentetik KDV','ACTIVE',maker,corr);
 insert into finance.tax_code_versions(id,tax_code_id,version_no,effective_from,calculation_method,rate,evidence_object_key,status,prepared_by,approved_by,approved_at_utc,created_by,correlation_id) values(tax_version,tax_code,1,date '2026-01-01','PERCENTAGE',0.20,'synthetic/tax','ACTIVE',maker,checker,now(),maker,corr);
 insert into finance.franchise_contracts(id,legal_entity_id,dealer_legal_entity_id,contract_code,status,created_by,correlation_id) values(contract_id,hq,dealer,'IMPACT-CONTRACT','ACTIVE',maker,corr);
 insert into finance.contract_versions(id,contract_id,version_no,currency_code,effective_from,content_hash,evidence_object_key,status,prepared_by,approved_by,approved_at_utc,created_by,correlation_id) values
 (active_version,contract_id,1,'TRY',date '2026-01-01',repeat('a',64),'synthetic/active','ACTIVE',maker,checker,now(),maker,corr),
 (candidate_version,contract_id,2,'TRY',date '2027-01-01',repeat('b',64),'synthetic/candidate','DRAFT',maker,null,null,maker,corr);
 insert into finance.document_references(id,legal_entity_id,external_document_id,document_type,storage_provider,object_key,content_hash,status,created_by,correlation_id) values(doc_ref,hq,doc_external,'FRANCHISE_AGREEMENT','SUPABASE_STORAGE','ototr-evidence/finance-contracts/sentetik-sozlesme.pdf',repeat('e',64),'ACTIVE',maker,corr);
 insert into finance.document_links(legal_entity_id,document_reference_id,subject_type,subject_id,purpose_code,created_by,correlation_id) values(hq,doc_ref,'CONTRACT_VERSION',candidate_version,'CONTRACT_VERSION_EVIDENCE_V1',maker,corr);
 insert into finance.contract_fee_rules(contract_version_id,fee_definition_id,rule_code,trigger_event_type,trigger_conditions,priority,status,configuration_status,basis_definition,calculation_method,calculation_parameters,tax_code_version_id,due_rule,cancellation_policy,price_includes_tax,currency_code,decimal_scale,rounding_mode,prepared_by,approved_by,approved_at_utc,created_by,correlation_id) values
 (active_version,fee_royalty,'ROYALTY-10','payment.settled','[]',100,'ACTIVE','CONFIGURED','{"kind":"COLLECTED_GROSS"}','PERCENTAGE','{"rate":"0.10"}',tax_version,'{}','{}',true,'TRY',2,'HALF_UP',maker,checker,now(),maker,corr),
 (candidate_version,fee_royalty,'ROYALTY-12','payment.settled','[]',100,'DRAFT','CONFIGURED','{"kind":"COLLECTED_GROSS"}','PERCENTAGE','{"rate":"0.12"}',tax_version,'{}','{}',true,'TRY',2,'HALF_UP',maker,null,null,maker,corr),
 (candidate_version,fee_entry,'ENTRY-100','contract.activated','[]',100,'DRAFT','CONFIGURED','{"kind":"FIXED"}','FIXED','{"amount":"100"}',tax_version,'{}','{}',false,'TRY',2,'HALF_UP',maker,null,null,maker,corr),
 (candidate_version,fee_unsupported,'TIERED-1','service.used','[]',100,'DRAFT','CONFIGURED','{"kind":"USAGE"}','TIERED','{"tiers":[{"upTo":"500","rate":"0.10"},{"upTo":null,"rate":"0.05"}]}',tax_version,'{}','{}',false,'TRY',2,'HALF_EVEN',maker,null,null,maker,corr);
 timeline:=finance_api.list_contract_versions(hq,account,branch,contract_id,null,25);
 if jsonb_array_length(timeline->'items')<>2 or timeline#>>'{items,0,versionNo}'<>'2' or timeline#>>'{items,0,ruleCount}'<>'3' or timeline#>>'{items,1,ruleCount}'<>'1' or jsonb_array_length(timeline#>'{items,0,documents}')<>1 or timeline#>>'{items,0,documents,0,documentId}'<>doc_external::text or (timeline->>'rawDefinitionsExposed')::boolean or (timeline->>'rawStorageKeysExposed')::boolean or timeline::text like '%synthetic/candidate%' or timeline::text like '%objectKey%' then raise exception 'safe contract timeline mismatch: %',timeline;end if;
 locator:=finance_api.get_contract_version_evidence_locator(hq,account,branch,candidate_version,doc_external);if locator->>'bucketId'<>'ototr-evidence' or locator->>'objectKey'<>'finance-contracts/sentetik-sozlesme.pdf' or locator->>'expiresIn'<>'120' or locator->>'rawStorageKeyExposed'<>'false' then raise exception 'contract evidence locator mismatch: %',locator;end if;
 select count(*) into before_count from finance.accruals;
 scenario:=jsonb_build_object('items',jsonb_build_array(jsonb_build_object('feeDefinitionId',fee_royalty,'basisAmount','1180','quantity','1'),jsonb_build_object('feeDefinitionId',fee_entry,'basisAmount','0','quantity','1')));
 result:=finance_api.simulate_contract_version_impact(hq,account,branch,active_version,candidate_version,scenario);
 if not(result->>'complete')::boolean or result#>>'{totals,activeGrossAmount}'<>'118.00' or result#>>'{totals,candidateGrossAmount}'<>'261.60' or result#>>'{totals,deltaGrossAmount}'<>'143.60' or (result->>'writesPerformed')::boolean or (result->>'rawDefinitionsExposed')::boolean then raise exception 'complete impact simulation mismatch: %',result;end if;
 scenario:=jsonb_set(scenario,'{items}',(scenario->'items')||jsonb_build_array(jsonb_build_object('feeDefinitionId',fee_unsupported,'basisAmount','1000','quantity','1')));
 result:=finance_api.simulate_contract_version_impact(hq,account,branch,active_version,candidate_version,scenario);
 if not(result->>'complete')::boolean or (result#>>'{items,2,candidate,grossAmount}')::numeric<>90.00 or (result#>>'{totals,candidateGrossAmount}')::numeric<>351.60 then raise exception 'tiered method simulation mismatch: %',result;end if;
 if (finance_private.simulate_rule_gross('COST_PLUS','{"markupRate":"0.10","markupAmount":"5"}',0.20,false,100,1,null,null,2,'UP')->>'grossAmount')::numeric<>138.00 then raise exception 'cost plus contract mismatch';end if;
 if (finance_private.simulate_rule_gross('CONDITIONAL','{"operator":"GTE","threshold":"100","whenMatched":{"method":"PERCENTAGE","parameters":{"rate":"0.10"}},"whenNotMatched":{"method":"FIXED","parameters":{"amount":"3"}}}',0,true,150,1,null,null,2,'HALF_EVEN')->>'grossAmount')::numeric<>15.00 then raise exception 'conditional contract mismatch';end if;
 if finance_private.simulate_rule_gross('TIERED','{"tiers":[]}',0,true,100,1,null,null,2,'HALF_UP')->>'reasonCode'<>'TIERED_PARAMETERS_INVALID' then raise exception 'invalid tier contract did not fail closed';end if;
 begin
   update finance.contract_fee_rules set calculation_parameters='{"tiers":[]}' where contract_version_id=candidate_version and fee_definition_id=fee_unsupported;
   raise exception 'invalid configured rule was persisted';
 exception when check_violation then null;end;
 if not finance_private.calculation_parameters_are_valid('CONDITIONAL','{"operator":"GTE","threshold":"100","whenMatched":{"method":"PERCENTAGE","parameters":{"rate":"0.10"}},"whenNotMatched":{"method":"FIXED","parameters":{"amount":"3"}}}',0) then raise exception 'valid conditional parameter contract rejected';end if;
 select count(*) into after_count from finance.accruals;if before_count<>after_count or exists(select 1 from finance.journal_entries where legal_entity_id=hq) or exists(select 1 from finance.open_items where legal_entity_id=hq) then raise exception 'simulation performed financial writes';end if;
end $test$;
rollback;
select 'CONTRACT IMPACT SIMULATION E2E PASSED' as result;
